/* Search helpers */
function normalizeArabic(s){
  s=(s||'').toString();
  // Arabic-Indic digits -> Latin
  s=s.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  s=s.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
  s=s.replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي');
  // normalize spoken number words (incl. Egyptian dialect) -> digits.
  // NOTE: \b is ASCII-only in JS, so use Unicode-aware letter boundaries.
  const WORD_B = '(?<![\\p{L}\\p{N}])';
  const WORD_E = '(?![\\p{L}\\p{N}])';
  const numW = {
    'واحد':'1',
    'اتنين|اتنان|اثنين|اثنتين':'2',
    'تلاته|تلات|ثلاثه|ثلاثة|ثلاث':'3',
    'اربع|اربعه|أربعة|أربع':'4',
    'خمسه|خمسة|خمس':'5',
    'سته|ستة|ست':'6',
    'سبعه|سبعة|سبع':'7',
    'تمانيه|تمانية|ثمانيه|ثمانية|ثماني':'8',
    'تسعه|تسعة|تسع':'9',
    'عشره|عشرة|عشر':'10',
    'عشرين|عشرون':'20',
    'تلاتين|ثلاثين':'30',
    'اربعين|أربعين':'40',
    'خمسين':'50',
    'ستين':'60',
    'سبعين':'70',
    'تمانين|ثمانين':'80',
    'تسعين':'90'
  };
  for (const k in numW) {
    s = s.replace(new RegExp(WORD_B + '(' + k + ')' + WORD_E, 'gu'), numW[k]);
  }
  // Egyptian half-meter phrase
  s = s.replace(new RegExp(WORD_B + 'متر\\s*(ونص|ونصف)' + WORD_E, 'gu'), '1.5 متر');
  return s;
}
function getItemByCode(code){
  if(!getItemByCode.__map){
    getItemByCode.__map=new Map();
    PRICE_LIST.forEach(i=>{ const k=String(i.code); if(!getItemByCode.__map.has(k)) getItemByCode.__map.set(k,i); });
  }
  return getItemByCode.__map.get(String(code));
}
function searchItems(q){
  q=(q||'').trim().toLowerCase();
  if(!q) return PRICE_LIST;
  const qn=normalizeArabic(q);
  return PRICE_LIST.filter(i=>{
    return String(i.code).toLowerCase().includes(q)
      || i.arDesc.toLowerCase().includes(q)
      || i.arNorm.includes(qn)
      || i.enNorm.includes(q)
      || i.group.toLowerCase().includes(q)
      || i.section.toLowerCase().includes(q)
  });
}

/* ================================================================
   Primary Pricing Reference — PRICING ATTACHMENT CSV (RFx 4000083770)
   File: js/data/pricing-reference.csv
   Parses the official BID FORM PRICING ATTACHMENT and refreshes the
   live PRICE_LIST prices from it. Handles Arabic-Indic digits (٠-٩),
   Arabic thousands (٬) and decimal (٫) separators, and quoted fields.
   ================================================================ */
function parsePriceReferenceCsv(text){
  const rows=[], row=[]; let field='', inQ=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(inQ){
      if(ch==='"'){ if(text[i+1]==='"'){ field+='"'; i++; } else inQ=false; }
      else field+=ch;
    } else {
      if(ch==='"') inQ=true;
      else if(ch===','){ row.push(field); field=''; }
      else if(ch==='\n'){ row.push(field); rows.push(row.slice()); row.length=0; field=''; }
      else if(ch==='\r'){ /* skip */ }
      else field+=ch;
    }
  }
  if(field!==''||row.length){ row.push(field); rows.push(row.slice()); }
  const AR={'٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9'};
  function toNum(s){
    if(s==null) return 0;
    s=String(s).trim().replace(/٬/g,'').replace(/٫/g,'.').replace(/%/g,'');
    s=s.replace(/[٠-٩]/g,d=>AR[d]);
    const v=parseFloat(s);
    return isNaN(v)?0:v;
  }
  const out={};
  for(const r of rows){
    const code=String(r[2]||'').trim();
    const ltype=String(r[3]||'').trim();
    if(!/^\d{9}$/.test(code)||ltype!=='Breakdown') continue;
    out[code]={
      arDesc:String(r[4]||'').trim(),
      uom:String(r[7]||'').trim(),
      qty:toNum(r[6]),
      oldPrice:toNum(r[8]),
      bidPrice:toNum(r[9]),
      newPrice:toNum(r[10]),
      incPct:toNum(r[11]),
      total:toNum(r[13])
    };
  }
  return out;
}

function refreshPricesFromReference(text){
  const ref=parsePriceReferenceCsv(text);
  const codes=Object.keys(ref);
  if(!codes.length) return { updated:0, total:0 };
  let updated=0;
  codes.forEach(code=>{
    const item=getItemByCode(code);
    if(!item) return;
    const r=ref[code];
    if(r.newPrice!==item.newPrice||r.oldPrice!==(item.oldPrice||0)||r.bidPrice!==item.bidPrice||r.qty!==item.qty||r.total!==item.total){
      item.newPrice=r.newPrice; item.oldPrice=r.oldPrice; item.bidPrice=r.bidPrice;
      item.qty=r.qty; item.total=r.total; item.incPct=r.incPct;
      if(r.uom) item.uom=r.uom;
      updated++;
    }
  });
  try{ localStorage.setItem('price_ref_source',JSON.stringify({ rfx:PRICE_LIST_META.rfx, appliedAt:new Date().toISOString(), count:updated })); }catch(e){}
  return { updated, total:codes.length };
}
